DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.metrics_inventory(jsonb)'::regprocedure) INTO d;d:=replace(d,'FUNCTION public.metrics_inventory(','FUNCTION public._metrics_inventory_base(');EXECUTE d;END $$;
CREATE OR REPLACE FUNCTION public.metrics_inventory(_scope jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH u AS(SELECT * FROM public.metrics_unit_scope u WHERE public.metrics_scope_match(u,_scope)) SELECT public._metrics_inventory_base(_scope)||jsonb_build_object('published_reserved',(SELECT count(*) FROM u WHERE publish_state='published' AND leasing_status IN('on_hold','pending_contract')),'status_counts',jsonb_build_object('leased',(SELECT count(*) FROM u WHERE leasing_status='leased'),'reserved',(SELECT count(*) FROM u WHERE leasing_status IN('on_hold','pending_contract')),'available',(SELECT count(*) FROM u WHERE leasing_status='available'),'maintenance',(SELECT count(*) FROM u WHERE leasing_status='maintenance'),'review',(SELECT count(*) FROM u WHERE leasing_status IS NULL))) $$;
REVOKE ALL ON FUNCTION public._metrics_inventory_base(jsonb) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public._metrics_inventory_base(jsonb) TO service_role;
SELECT to_regprocedure('public._metrics_inventory_base(jsonb)') IS NOT NULL AS inventory_ready;